    (3, 3697, 3697, 'MASEIN, SOCIEDAD ANÓNIMA', null, '120092670', '120092670', null, null, '11 CALLE COLONIA VISTA HERMOSA III 18-02, LOCAL 5 ZONA 15,GUATEMALA', null, null, 1, 'S', false, 'A', 'MASEIN', 'MASEIN', null, false, null, null, null, null, 3, null, null, 0, true, null, 1, false, 'MASEIN, SOCIEDAD ANÓNIMA'),
    (3, 3698, 3698, 'JORGE FERNANDO, CULAJAY REYES', null, '24805092', '24805092', null, null, '12 CALLE  2-04 EDIFICIO PLAZA DEL SOL LOCAL 5, ZONA 9,GUATEMALA', null, null, 1, 'S', false, 'A', 'SELLOS INNOVA', 'SELLOS INNOVA', null, false, null, null, null, null, 3, null, null, 0, true, null, 1, false, 'JORGE FERNANDO, CULAJAY REYES'),
    (3, 3699, 3699, 'PRODUCTOS SUPERB ESPECIAS, S.A.', null, '1698826', '1698826', null, null, '6 CALLE 26-50 PARQUE COMERCIAL LAS MAJADAS LOCAL 24ZONA 11 GUATEMALA', null, null, 1, 'S', false, 'A', 'PRODUCTOS SUPERB ESPECIAS', 'PRODUCTOS SUPERB ESPECIAS', null, false, null, null, null, null, 3, null, null, 0, true, null, 1, false, 'PRODUCTOS SUPERB ESPECIAS, S.A'),
    (3, 3703, 3703, 'LIGIA ANDREA BOLOIX MORÁN DE ALDANA', null, '86416227', '86416227', null, null, '0 CALLE B 17-42 COLONIA EL MAESTRO, ZONA 15, GUATEMALA', null, null, 1, 'S', false, 'A', 'LIGIA ANDREA BOLOIX MORÁN DE ALDANA', 'LIGIA ANDREA BOLOIX MORÁN DE ALDANA', null, false, null, null, null, null, 4, null, null, 0, true, null, 1, false, 'LIGIA ANDREA BOLOIX MORÁN DE ALDANA')) as x(loc, codigo, anterior, nombre, razon, nit, nit_ant, telefonos, contacto, direccion, extension, fax, tipo, origen, critico, estado,
       comercial, emision, banco, retencion, centro, usr_mod, f_mod, correo, regimen, clasif_act, forma_pago, dias, mostrar, cuenta, version, pendiente, concepto) loop
    select id into v_loc from public.localidades where organizacion_id = v_org and correlativo = r.loc;
    if v_loc is null then
      if position(format('2-0%s', r.loc) in v_omit) = 0 then v_omit := v_omit || format(' 2-0%s', r.loc); end if;
      continue;
    end if;
    v_id := null;
    select id into v_id from public.proveedores where localidad_id = v_loc and codigo = r.codigo;
    v_nit := r.nit;
    if v_nit is not null and v_nit not in ('CF', 'C/F') and exists (select 1 from public.proveedores where localidad_id = v_loc and nit = v_nit and id is distinct from v_id) then
      v_nit := null; n_q := n_q + 1;
    end if;
    v_cuenta := null;
    if r.cuenta is not null then
      select k.id into v_cuenta from public.cuentas k join public.catalogos_cuentas g on g.id = k.catalogo_id
      where g.localidad_id = v_loc and k.codigo = r.cuenta and (g.version = r.version or r.version is null) order by g.version desc limit 1;
      if v_cuenta is null then s_cta := s_cta + 1; end if;
    end if;
    v_banco := (select x.id from public.bancos x where x.localidad_id = v_loc and x.codigo = r.banco);
    if r.banco is not null and v_banco is null then s_ban := s_ban + 1; end if;
    v_centro := (select c.id from public.centros_costo c join public.catalogos_centros k on k.id = c.catalogo_id
                 where k.localidad_id = v_loc and c.codigo = r.centro::text order by (k.version = 1) desc, k.activo desc limit 1);
    if v_id is null then
      insert into public.proveedores (organizacion_id, localidad_id, codigo, nombre_comercial, concepto_gastos)
      values (v_org, v_loc, r.codigo, coalesce(r.comercial, r.nombre), coalesce(r.concepto, 'POR DEFINIR')) returning id into v_id;
      p_n := p_n + 1;
    else
      p_a := p_a + 1;
    end if;
    update public.proveedores set
      nit = v_nit, nit_anterior = r.nit_ant, nombre_comercial = coalesce(r.comercial, r.nombre), nombre_fiscal = coalesce(r.razon, r.nombre),
      nombre_emision = r.emision, razon_social = r.razon, direccion = r.direccion, concepto_gastos = coalesce(r.concepto, 'POR DEFINIR'),
      telefonos = r.telefonos, extension = r.extension, contacto = r.contacto, correo = r.correo, fax = r.fax,
      nacional = coalesce(r.tipo, 1) = 1, servicio_critico = coalesce(r.critico, false), pendiente_revisar = coalesce(r.pendiente, false),
      tipo_proveedor_id = (select t.id from public.tipos_proveedor t where t.codigo = r.tipo),
      regimen_isr_id = (select g.id from public.regimenes_isr g where g.codigo = r.regimen), regimen_isr_anterior = r.regimen,
      estado = case when r.estado = 'I' then 'INACTIVO' else 'ACTIVO' end, dias_credito = coalesce(r.dias, 0),
      efectuar_retencion = coalesce(r.retencion, false), cuenta_gasto_id = v_cuenta, cuenta_gasto_codigo = r.cuenta, version = r.version,
      forma_pago = case when r.forma_pago = 'R' then 'TRANSFERENCIA' else 'CHEQUE' end, forma_pago_anterior = r.forma_pago,
      banco_id = v_banco, banco_anterior = r.banco, centro_id = v_centro, centro_costo_anterior = r.centro::text,
      origen = r.origen, mostrar = r.mostrar, clasificacion_actividad = r.clasif_act, proveedor_anterior = r.anterior,
      usuario_modifica_anterior = r.usr_mod, fecha_modifica_anterior = r.f_mod, origen_anterior = 'MIGRADO'
    where id = v_id;
  end loop;

  raise notice '%', format('Proveedores de la organización 2 (parte 3 de 4): %s nuevos, %s actualizados. Creados: %s regímenes ISR y %s centros de costo.%s%s%s%s',
    p_n, p_a, g_n, c_n,
    case when n_q > 0 then format(' %s con un NIT que ya tiene otro proveedor de la localidad (queda en nit_anterior).', n_q) else '' end,
    case when s_cta > 0 then format(' %s con una cuenta de gastos que no existe en el catálogo (queda su código).', s_cta) else '' end,
    case when s_ban > 0 then format(' %s con un banco que no existe en la localidad (queda su código).', s_ban) else '' end,
    case when v_omit <> '' then ' Localidades que no existen (omitidas):' || v_omit || '.' else '' end);
end;
$prov$;
